<?php
namespace axenox\GenAI\Common\Messages;

use axenox\GenAI\DataTypes\AiMessageTypeDataType;
use exface\Core\Interfaces\Filesystem\FileInfoInterface;

/**
 * Something the model said - e.g. an answer of the LLM, optionally with generated files
 * 
 * A structured answer (JSON mode) is kept as the JSON text produced by the LLM.
 * 
 * @author Andrej Kabachnik
 */
class OutputMessage extends AbstractAiMessage
{
    /**
     * @param string $text
     * @param FileInfoInterface[] $attachments Files generated by the model
     * @param array<string,array<array-key,mixed>> $adapterData
     * @param string $type AiMessageTypeDataType value for subclasses with other output types
     */
    public function __construct(string $text, array $attachments = [], array $adapterData = [], string $type = AiMessageTypeDataType::ASSISTANT)
    {
        parent::__construct($type, $text, $attachments, $adapterData);
    }

    /**
     * {@inheritDoc}
     * @see AbstractAiMessage::isOutput()
     */
    public function isOutput() : bool
    {
        return true;
    }

    /**
     * Renders JSON answers as pretty-printed code blocks, other answers as-is
     * 
     * {@inheritDoc}
     * @see AbstractAiMessage::toMarkdown()
     */
    public function toMarkdown() : string
    {
        $text = $this->getText();
        $trimmed = ltrim($text);
        if ($trimmed !== '' && ($trimmed[0] === '{' || $trimmed[0] === '[')) {
            try {
                $json = json_decode($text, false, 512, JSON_THROW_ON_ERROR);
                $text = "```json\n" . json_encode($json, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . "\n```";
            } catch (\JsonException $e) {
                // Not JSON - render as-is
            }
        }
        return $text . $this->buildAttachmentsMarkdown();
    }
}
